async function getShareUrl() {
  // Try to read clipboard if permission is granted
  try {
    const text = await navigator.clipboard.readText();
    if (text) return { source: 'clipboard', url: text };
  } catch (e) {
    // Clipboard permission denied
  }

  // Find the share link in the dialog
  const dialog = document.querySelector('[role="dialog"]') || document.querySelector('.app-container');
  const dialogText = document.body.innerText;

  // Look for links with maps.app.goo.gl or google.com/maps
  const links = [];
  document.querySelectorAll('a').forEach(a => {
    if (a.href && (a.href.includes('maps.app.goo.gl') || a.href.includes('google.com/maps'))) {
      links.push({href: a.href, text: a.textContent.trim()});
    }
  });

  // Look for input fields containing the URL
  const inputs = [];
  document.querySelectorAll('input').forEach(i => {
    if (i.value && (i.value.includes('maps.app.goo.gl') || i.value.includes('google.com/maps'))) {
      inputs.push({value: i.value, type: i.type});
    }
  });

  return {links, inputs, dialogText: dialogText.substring(0, 2000)};
}
return getShareUrl();

function getShareUrl() {
  // Find the share link in the dialog
  const links = [];
  document.querySelectorAll('a').forEach(a => {
    if (a.href && (a.href.includes('maps.app.goo.gl') || a.href.includes('google.com/maps'))) {
      links.push({href: a.href, text: a.textContent.trim().substring(0, 100)});
    }
  });

  // Look for input fields containing the URL
  const inputs = [];
  document.querySelectorAll('input').forEach(i => {
    if (i.value && (i.value.includes('maps.app.goo.gl') || i.value.includes('google.com/maps'))) {
      inputs.push({value: i.value, type: i.type});
    }
  });

  return {links, inputs};
}
return getShareUrl();

function findShareUrl() {
  // Find all elements containing 'maps.app.goo.gl' or share-related text
  const allElements = document.querySelectorAll('*');
  const matches = [];
  for (const el of allElements) {
    if (el.children.length === 0) {
      const text = el.textContent || '';
      if (text.includes('goo.gl') || text.includes('google.com/maps') || text.includes('share')) {
        matches.push({
          tag: el.tagName,
          text: text.substring(0, 200),
          id: el.id,
          className: el.className,
          attrs: Array.from(el.attributes).map(a => `${a.name}="${a.value.substring(0, 100)}"`).join(' ')
        });
      }
    }
  }
  return matches;
}
return findShareUrl();

function exploreShareDialog() {
  // Find the element with maps.app.goo.gl
  const target = document.querySelector('[data-hl-idx="2354"]');
  if (!target) return { error: 'target not found' };

  // Walk up the tree to find related elements
  let parent = target.parentElement;
  const result = { target: target.outerHTML.substring(0, 500), parent: parent ? parent.outerHTML.substring(0, 2000) : null };

  // Look for any element with data-* attributes related to share
  const dialogContent = document.querySelector('.app-container, [role="dialog"], .mLuXmc, [aria-label*="分享"]');
  if (dialogContent) {
    result.dialogContent = dialogContent.outerHTML.substring(0, 3000);
  }

  // Get full inner text of body in case the URL is somewhere
  const allText = document.body.innerText;
  const urlMatches = allText.match(/https?:\/\/[^\s\n]+/g);
  result.urlMatches = urlMatches;

  return result;
}
return exploreShareDialog();

function getCurrentLocation() {
  return {
    url: window.location.href,
    location: window.location.toString(),
    pathname: window.location.pathname,
    search: window.location.search,
    hash: window.location.hash
  };
}
return getCurrentLocation();

function findShareInfo() {
  // Check for any data attributes, hidden elements, or specific Google Maps share info
  const results = {};

  // Check the copy link button and its handlers
  const copyBtn = document.querySelector('#app-container-Copy Link');
  results.copyBtn = copyBtn ? copyBtn.outerHTML.substring(0, 1000) : null;

  // Check for any element with data-url, data-link, etc.
  const dataAttrs = document.querySelectorAll('[data-url], [data-share-url], [data-link]');
  results.dataAttrs = Array.from(dataAttrs).map(el => ({tag: el.tagName, attrs: Array.from(el.attributes).map(a => `${a.name}=${a.value.substring(0, 200)}`)}));

  // Look for hidden inputs
  const inputs = document.querySelectorAll('input[type="hidden"], input[readonly]');
  results.hiddenInputs = Array.from(inputs).map(i => ({type: i.type, value: i.value, id: i.id}));

  // Look for JavaScript variables
  results.windowKeys = Object.keys(window).filter(k => k.toLowerCase().includes('share') || k.toLowerCase().includes('goo') || k.toLowerCase().includes('url'));

  // Check the entire dialog HTML for any URL hints
  const dialog = document.querySelector('[role="dialog"][aria-modal="true"]');
  results.fullDialog = dialog ? dialog.outerHTML.substring(0, 5000) : null;

  return results;
}
return findShareInfo();

function exploreShareState() {
  const results = {};

  // Check for JavaScript variables that might contain the share URL
  results.hasSharekitGlobal = typeof window.sharekit !== 'undefined';
  results.hasMapsApi = typeof window.google?.maps !== 'undefined';

  // Look for any element with classes related to share
  const shareClasses = ['tNuAdd', 'we99Fd', 'whdmFb', 'pAvKO'];
  shareClasses.forEach(cls => {
    const els = document.querySelectorAll(`.${cls}`);
    results[cls] = Array.from(els).map(el => ({
      text: el.textContent,
      attrs: Array.from(el.attributes).map(a => `${a.name}="${a.value}"`)
    }));
  });

  // Look for the application div that might contain state
  const appDiv = document.querySelector('[sharekit-id="tYwGbe"]');
  if (appDiv) {
    results.sharekitApp = {
      attrs: Array.from(appDiv.attributes).map(a => `${a.name}="${a.value}"`),
      childKeys: Array.from(appDiv.children).map(c => c.tagName)
    };
    // Try to get internal state
    try {
      const reactPropsKey = Object.keys(appDiv).find(k => k.startsWith('__reactProps') || k.startsWith('__reactFiber'));
      if (reactPropsKey) {
        const props = appDiv[reactPropsKey];
        const keys = Object.keys(props || {});
        results.reactKeys = keys;
        // Look for URL or share-related keys
        const urlKeys = keys.filter(k => k.toLowerCase().includes('url') || k.toLowerCase().includes('share') || k.toLowerCase().includes('link'));
        results.urlRelatedKeys = urlKeys;
      }
    } catch(e) {
      results.reactError = e.message;
    }
  }

  // Check if there's any state in the sharekit container
  const sharekitContainer = document.querySelector('[data-skw-id="container"]');
  if (sharekitContainer) {
    const reactPropsKey = Object.keys(sharekitContainer).find(k => k.startsWith('__reactProps') || k.startsWith('__reactFiber'));
    if (reactPropsKey) {
      const props = sharekitContainer[reactPropsKey];
      if (props) {
        const keys = Object.keys(props);
        results.containerKeys = keys;
      }
    }
  }

  return results;
}
return exploreShareState();

function findReactShareUrl() {
  const results = {};

  // Find all elements with share-related attributes
  const allEls = document.querySelectorAll('*');
  const reactPropsMap = [];

  for (const el of allEls) {
    const reactPropsKey = Object.keys(el).find(k => k.startsWith('__reactProps'));
    if (!reactPropsKey) continue;

    const props = el[reactPropsKey];
    if (!props) continue;

    // Check if any props contain URL info
    const urlRelated = {};
    for (const key of Object.keys(props)) {
      const val = props[key];
      if (typeof val === 'string' && (val.includes('goo.gl') || val.includes('maps'))) {
        urlRelated[key] = val.substring(0, 200);
      }
      if (typeof val === 'object' && val !== null) {
        const str = JSON.stringify(val).substring(0, 1000);
        if (str.includes('goo.gl') || str.includes('maps.app')) {
          urlRelated[key] = str;
        }
      }
    }

    if (Object.keys(urlRelated).length > 0) {
      const elInfo = {
        tag: el.tagName,
        id: el.id,
        className: typeof el.className === 'string' ? el.className.substring(0, 100) : '',
        urlRelated: urlRelated
      };
      reactPropsMap.push(elInfo);
    }
  }

  results.reactPropsWithUrl = reactPropsMap;

  // Also try to find any textContent that might be hidden or stored
  const linkSpan = document.querySelector('[data-hl-idx="3505"]');
  if (linkSpan) {
    results.linkSpanInfo = {
      text: linkSpan.textContent,
      parent: linkSpan.parentElement.outerHTML.substring(0, 500),
      attrs: Array.from(linkSpan.attributes).map(a => `${a.name}="${a.value}"`)
    };
    // Check React state of this element
    const reactPropsKey = Object.keys(linkSpan).find(k => k.startsWith('__reactProps'));
    if (reactPropsKey) {
      results.linkSpanReact = JSON.stringify(linkSpan[reactPropsKey]).substring(0, 2000);
    }
  }

  return results;
}
return findReactShareUrl();

function setupNetworkCapture() {
  window.__capturedUrls = [];
  const origFetch = window.fetch;
  window.fetch = async function(...args) {
    const url = args[0];
    if (typeof url === 'string' && (url.includes('share') || url.includes('goo.gl') || url.includes('shorturl'))) {
      window.__capturedUrls.push({type: 'fetch', url: url});
    }
    return origFetch.apply(this, args);
  };

  const origXHR = window.XMLHttpRequest.prototype.open;
  window.XMLHttpRequest.prototype.open = function(method, url) {
    if (typeof url === 'string' && (url.includes('share') || url.includes('goo.gl') || url.includes('shorturl'))) {
      window.__capturedUrls.push({type: 'xhr', url: url});
    }
    return origXHR.apply(this, arguments);
  };

  return 'Network capture set up';
}
return setupNetworkCapture();

function checkCaptured() {
  return {
    capturedUrls: window.__capturedUrls || [],
    clipboardContents: 'cannot read directly'
  };
}
return checkCaptured();
